export declare const railsStyles = "\n/* ---- \u5DE6\u4FA7\u8D44\u6E90\u6811\u5BB9\u5668 ---- */\n.wf-docrail {\n  flex: none;\n  width: auto;\n  display: flex;\n  flex-direction: column;\n  background: var(--wf-layer);\n  min-height: 0;\n  overflow: hidden;\n}\n\n.wf-docrail.is-collapsed {\n  visibility: hidden;\n  pointer-events: none;\n  width: 0;\n}\n\n.wf-docrail__list {\n  flex: 1 1 0;\n  height: 0;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  padding: 9px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  scrollbar-width: thin;\n}\n\n/* ---- \u5DE6\u680F\u6807\u7B7E\u9875 ---- */\n.wf-lib-tabs {\n  flex: none;\n  display: flex;\n  gap: 4px;\n  padding: 8px 10px 0;\n  border-bottom: 1px solid var(--wf-border);\n}\n\n.wf-lib-tab {\n  flex: 1;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  border: 0;\n  border-radius: 9px 9px 0 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  padding: 7px 4px;\n  font-size: 11px;\n  font-weight: 650;\n  cursor: pointer;\n}\n\n.wf-lib-tab:hover {\n  color: var(--wf-ink);\n  background: color-mix(in srgb, var(--wf-brand) 6%, transparent);\n}\n\n.wf-lib-tab.is-active {\n  color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 10%, transparent);\n  box-shadow: inset 0 -2px 0 var(--wf-brand);\n}\n\n/* ---- \u5E95\u680F\uFF08\u65B0\u589E\uFF1B\u4E0E\u5DE6\u680F\u76F8\u4E92\u5207\u6362\uFF1B\u5361\u7247\u6A2A\u5411 flex-wrap \u52A8\u6001\u8FFD\u52A0\u6392\uFF09 ---- */\n.wf-bottom-area {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.wf-bottombar {\n  flex: none;\n  display: flex;\n  flex-direction: row;\n  background: var(--wf-layer);\n  border-top: 1px solid var(--wf-border);\n  min-height: 0;\n  overflow: hidden;\n}\n\n.wf-bottombar.is-collapsed {\n  visibility: hidden;\n  pointer-events: none;\n  height: 0;\n}\n\n/* Tag \u533A\uFF1A\u4F4D\u4E8E\u5E95\u680F\u3010\u5DE6\u4FA7\u3011\uFF08\u7AD6\u5411\u6392\u5E03\uFF09\uFF0C\u4F46\u6BCF\u4E2A Tag \u6587\u5B57\u662F\u3010\u6A2A\u5411\u3011\u7684\uFF08\u5DE5\u4F5C\u6D41/\u89D2\u8272/\u6570\u636E/\u5176\u4ED6\uFF09\uFF0C\u4E0D\u663E\u793A\u56FE\u6807 */\n.wf-bottombar__tags {\n  flex: none;\n  width: 88px;\n  display: flex;\n  flex-direction: column;\n  align-items: stretch;\n  gap: 2px;\n  padding: 8px 6px;\n  border-right: 1px solid var(--wf-border);\n}\n\n.wf-bottombar__tag {\n  border: 1px solid transparent;\n  border-radius: 8px;\n  background: transparent;\n  color: var(--wf-ink-2);\n  padding: 7px 8px;\n  font-size: 11px;\n  font-weight: 650;\n  cursor: pointer;\n  white-space: nowrap;\n  text-align: center;\n}\n\n.wf-bottombar__tag:hover {\n  color: var(--wf-ink);\n  background: color-mix(in srgb, var(--wf-brand) 6%, transparent);\n}\n\n.wf-bottombar__tag.is-active {\n  color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 10%, transparent);\n  border-color: color-mix(in srgb, var(--wf-brand) 45%, var(--wf-border));\n}\n\n.wf-bottombar__scroll {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  padding: 8px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  scrollbar-width: thin;\n}\n\n.wf-bottombar__section {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.wf-bottombar__group {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 10px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--wf-ink-2);\n}\n\n.wf-bottombar__group-title {\n  flex: none;\n  white-space: nowrap;\n}\n\n.wf-bottombar__cards {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  align-content: flex-start;\n}\n\n/* \u5E95\u680F\u5361\u7247\uFF1A\u53EA\u663E\u793A\u540D\u79F0\uFF08\u56FE\u7247\u6279\u6CE8\uFF1A\u4E0D\u518D\u663E\u793A\u63CF\u8FF0\u548C\u5176\u4ED6\u5185\u5BB9\uFF0C\u5305\u62EC\u56FE\u6807\uFF09 */\n.wf-hcard {\n  max-width: 180px;\n  min-width: 96px;\n  height: 32px;\n  padding: 0 12px;\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  font-size: 11px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  cursor: grab;\n  touch-action: none;\n  transition: border-color .14s ease, background .14s ease;\n}\n\n.wf-hcard:hover {\n  border-color: color-mix(in srgb, var(--wf-brand) 55%, var(--wf-border-strong));\n}\n\n.wf-hcard.is-active {\n  border-color: color-mix(in srgb, var(--wf-brand) 45%, var(--wf-border));\n  background: color-mix(in srgb, var(--wf-brand) 12%, var(--wf-layer));\n  color: var(--wf-brand);\n}\n\n.wf-hcard__name {\n  display: block;\n  width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* \u5E95\u680F\u4E0A\u8FB9\u754C\u62D6\u52A8\u7EBF\uFF08\u6C34\u5E73\u3001\u4F4D\u4E8E\u5E95\u680F\u9876\u90E8\uFF0C\u4E0A\u4E0B\u8C03\u6574\u5927\u5C0F\uFF1B\u56FE\u7247\u6279\u6CE8\uFF1A\u8FB9\u754C\u7EBF\u540C\u6837\u53EF\u62D6\u52A8\uFF09\u3002\n   \u53CC\u7C7B\u9009\u62E9\u5668\u8986\u76D6 .wf-splitter \u7684\u7AD6\u5411\u9ED8\u8BA4\uFF08width:9px/col-resize\uFF09\uFF0C\u786E\u4FDD\u4E3A\u6A2A\u5411\u3002 */\n.wf-splitter.wf-splitter--horizontal {\n  position: relative;\n  z-index: 12;\n  flex: none;\n  min-width: 0;\n  width: auto;\n  min-height: 8px;\n  height: 8px;\n  cursor: row-resize;\n  touch-action: none;\n  background: var(--wf-layer-2);\n  outline: 0;\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-splitter.wf-splitter--horizontal::before {\n  content: \"\";\n  position: absolute;\n  inset: 3px 0;\n  background: var(--wf-border);\n}\n\n.wf-splitter.wf-splitter--horizontal:hover::before,\n.wf-splitter.wf-splitter--horizontal:focus-visible::before,\n.wf-splitter.wf-splitter--horizontal.is-dragging::before {\n  inset: 2px 0;\n  background: var(--wf-brand);\n}\n\n/* ---- \u8D44\u6E90\u6761\u76EE\uFF08\u5206\u7EC4 / \u6761\u76EE / \u5FBD\u6807\uFF09 ---- */\n.wf-docgroup {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 5px 7px 2px;\n  font-size: 10px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--wf-ink-2);\n}\n\n.wf-docgroup__add {\n  width: 20px;\n  height: 20px;\n  min-width: 20px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 6px;\n  background: transparent;\n  color: var(--wf-ink-2);\n  font-size: 13px;\n  line-height: 0;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n}\n\n.wf-docgroup__add:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n}\n\n.wf-docitem {\n  width: 100%;\n  display: grid;\n  grid-template-columns: 26px minmax(0, 1fr) auto;\n  gap: 9px;\n  align-items: center;\n  text-align: left;\n  border: 1px solid transparent;\n  border-radius: 10px;\n  background: transparent;\n  color: var(--wf-ink);\n  padding: 8px;\n  cursor: grab;\n  touch-action: none;\n}\n\n.wf-docitem:hover {\n  background: var(--wf-layer-2);\n  border-color: var(--wf-border);\n}\n\n.wf-docitem.is-active {\n  background: color-mix(in srgb, var(--wf-brand) 10%, var(--wf-layer));\n  border-color: color-mix(in srgb, var(--wf-brand) 45%, var(--wf-border));\n  color: var(--wf-brand);\n}\n\n.wf-docitem.is-pinned {\n  background: color-mix(in srgb, var(--wf-brand) 6%, var(--wf-layer));\n  border-color: color-mix(in srgb, var(--wf-brand) 28%, var(--wf-border));\n}\n\n.wf-docitem__icon {\n  width: 26px;\n  height: 30px;\n  border: 1px solid currentColor;\n  border-radius: 6px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 9px;\n  font-weight: 800;\n  opacity: .76;\n}\n\n.wf-docitem__texts {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  min-width: 0;\n}\n\n.wf-docitem__title-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n\n.wf-docitem__title-row .wf-docitem__label {\n  flex: 0 1 auto;\n  min-width: 0;\n}\n\n.wf-docitem__title-row .wf-docitem__badge {\n  flex: none;\n  margin-left: 0;\n}\n\n.wf-docitem__label {\n  display: block;\n  font-size: 12px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.wf-docitem__path {\n  display: block;\n  font: 9px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;\n  color: var(--wf-ink-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.wf-docitem__badge {\n  justify-self: end;\n  white-space: nowrap;\n  font-size: 10px;\n  font-weight: 700;\n  color: var(--wf-ok);\n  border: 1px solid color-mix(in srgb, var(--wf-ok) 40%, var(--wf-border));\n  border-radius: 6px;\n  padding: 2px 7px;\n  background: color-mix(in srgb, var(--wf-ok) 12%, transparent);\n}\n\n/* \u5DE5\u4F5C\u53F0\u5168\u5C40\u5316\uFF1A\u300C\u5F53\u524D\u300D\u5FBD\u6807\uFF08\u5F53\u524D\u4E3B\u4F1A\u8BDD\u5BF9\u5E94\u7684\u5B9E\u4F8B\uFF1B\u54C1\u724C\u8272\u4EE5\u533A\u5206\u666E\u901A\u72B6\u6001\u5FBD\u6807\uFF09 */\n.wf-docitem__badge.is-current {\n  color: var(--wf-brand);\n  border-color: color-mix(in srgb, var(--wf-brand) 45%, var(--wf-border));\n  background: color-mix(in srgb, var(--wf-brand) 12%, transparent);\n}\n\n/* ---- \u62D6\u62FD\u9884\u89C8\u6D6E\u6807 ---- */\n.wf-drag-preview {\n  position: fixed;\n  z-index: 999;\n  pointer-events: none;\n  min-width: 150px;\n  max-width: 230px;\n  padding: 9px 12px;\n  border: 1px solid var(--wf-brand);\n  border-radius: 10px;\n  background: color-mix(in srgb, var(--wf-layer) 94%, var(--wf-brand) 6%);\n  color: var(--wf-ink);\n  font-size: 12px;\n  font-weight: 650;\n  box-shadow: 0 14px 34px color-mix(in srgb, var(--wf-ink) 22%, transparent);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n";
